if ~exist('src400','var')
    src400 = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei401_align.sqw');
end
if ~exist('src400sym','var')
    src400sym = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei401_align_sym3.sqw ');
end
hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;

w2_000a = cut(src400sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[95,105]);
plot(w2_000a);liny; lz 0 2;keep_figure; %[output:7906b6dc]
w2_000b = cut(src400sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[45,55]);
plot(w2_000b);lz 0 2; keep_figure; %[output:67699388]


hc.log_level = ll;

othrEi400cut110 = {[-0.1,0.1],[-0.1,0.1],[0,2,260]};
file = src400sym.full_filename %[output:4c828ed2]
[~,fname] = fileparts(file);

% recover masks not to draw them again
[cuts2fit400NG,masks_file]  = recover_selected_cuts('cuts2fit400NG', ...
    'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits');
% retrieve selected cuts used for further fitting
[NG_FFCutsFits,allJfitfile] = recover_selected_cuts('NG_FFCutsFits', ...
    'e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');
%%


%%
hc.log_level = -2;
e0=150;
w2_001 = cut(src400sym,line_proj('offset',[0,0,0]),0.04,0.04,[-0.1,0.1],[e0-10,e0+10]);
plot(w2_001);lz 0 0.4; liny; keep_figure; %[output:38d4389e]

w2_00 = cut(src400sym,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]);
plot(w2_00);lz 0 1; %[output:62e37844]
keep_figure; %[output:62e37844]

w2_00 = cut(src400sym,line_proj(),0.04,0.04,[-0.1,0.1],[245,255]);
plot(w2_00);lz 0 0.1; %[output:4575df4d]
keep_figure; %[output:4575df4d]

w2_00 = cut(src400sym,line_proj(),0.02,0.02,[-0.1,0.1],[255,265]);
plot(w2_00);lz 0 0.1; %[output:7cda4b93]
keep_figure; %[output:7cda4b93]


hc.log_level = ll;

%%
% <200> and <110> cuts along min FF change line
lpm110of110 = line_proj([-1,1,0],[1,1,0],'offset',[1,1,0]);
w2_400NG = cut(src400sym,lpm110of110,[-1,0.02,1],othrEi400cut110{:}); %[output:70786236]
plot(w2_400NG);lz 0 1; keep_figure %[output:581873c3]

fh = plot(w2_400NG); liny; lz 0 4; %[output:1a5868f9]
[w2_400NGfit,cuts2fit400NG] = draw_masks_helper(fh,cuts2fit400NG,'msk110_dirM110',3);
plot(w2_400NGfit); lz 0 1; keep_figure; %[output:1a5868f9]

%cuts2fit400NG.all_cff_cuts = {w2_400NGfit};
%%
w2_400NGns = cut(src400,lpm110of110,[-1,0.02,1],othrEi400cut110{:}); %[output:085e9070]
fh = plot(w2_400NGns);lz 0 4; keep_figure %[output:10ea871f]
[w2_400NGns,cuts2fit400NG] = draw_masks_helper(fh,cuts2fit400NG,'msk110_dirM110_nonSym',4); %[output:10ea871f]
plot(w2_400NGns); lz 0 1; keep_figure; %[output:051ba24a]
cuts2fit400NG.all_cff_cuts = {w2_400NGns};
%%
save(masks_file,'cuts2fit400NG','-v7.3');
%%
% <110> min FF change cut

w2_400NGfits = cut(w2_400NGfit,[0,0.005,0.5],[10,2,175],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0])); %[output:783af5aa]
plot(w2_400NGfits);lz 0 1; keep_figure; %[output:778c9548]
% <100> min FF change cut unsummeterized:
w2_400NGnsf = cut(w2_400NGns,[-0.5,0.01,0.5],[10,2,175]); %[output:5766b300]
plot(w2_400NGnsf);lz 0 1; keep_figure; %[output:9a588b82]
%%

NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei400_off110NGminFF',w2_400NGfits);
%%
NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei400_off110NGminFFns',w2_400NGnsf);

%%
% specialized <200> cut with min FF change
lpm110of200 = line_proj([-1,1,0],[1,1,0],'offset',[2,0,0]);
w2_400NGOff200 = cut(w2_400NGfit,lpm110of200,[0,0.005,0.5],othrEi400cut110{:},SymopReflection('normvec',[1,-1,0],'offset',[1,1,0])); %[output:5adc6097]
plot(w2_400NGOff200);lz 0 1; %[output:8093ddc7]
%%


NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei400_off200NGminFF',w2_400NGOff200);
%%
% <110> cut with max FF change
lp110of110 = line_proj([1,1,0],[1,-1,0],'offset',[1,1,0]);
w2_400NGoff110maxFF = cut(src400sym,lp110of110,[-1,0.02,3],othrEi400cut110{:}); %[output:9b0edda9]
fh = plot(w2_400NGoff110maxFF); liny; lz 0 1; %[output:25a67e11]
[w2_400NGoff110maxFF,cuts2fit400NG] = draw_masks_helper(fh, ...
    cuts2fit400NG, 'msk110_dir110',3);
plot(w2_400NGoff110maxFF); lz 0 1; keep_figure; %[output:25a67e11]
%%
NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei400_off110NGmaxFF',cut(w2_400NGoff110maxFF,[0,0.005,0.5],[10,2,200]));
%%
% <200> cut with max FF change
lp110of200 = line_proj([1,1,0],[1,-1,0],'offset',[2,0,0]);
w2_400NGoff200maxFF = cut(src400sym,lp110of200,[-1,0.02,3],othrEi400cut110{:}); %[output:39a59e11]
fh = plot(w2_400NGoff200maxFF); liny; lz 0 1; %[output:0485f1ce]
[w2_400NGoff200maxFF,cuts2fit400NG] = draw_masks_helper(fh, ...
    cuts2fit400NG, 'msk200_dir110',3);
plot(w2_400NGoff200maxFF); lz 0 1; keep_figure; %[output:0485f1ce]

lp110of020 = line_proj([1,1,0],[1,-1,0],'offset',[0,2,0]);
w2_400NGoff020maxFF = cut(src400sym,lp110of020,[-1,0.02,3],othrEi400cut110{:}); %[output:82513560]
fh = plot(w2_400NGoff020maxFF); liny; lz 0 1; %[output:2cce91b0]
[w2_400NGoff020maxFF,cuts2fit400NG] = draw_masks_helper(fh, ...
    cuts2fit400NG, 'msk020_dir110',3);
plot(w2_400NGoff020maxFF); lz 0 1; keep_figure; %[output:2cce91b0]

w2ei400NGoff200maxFF = sqw_op_bin_pixels({w2_400NGoff200maxFF,w2_400NGoff020maxFF}, ... %[output:group:80995a45] %[output:16cc5ecb]
    @move_all_to_proj, ... %[output:16cc5ecb]
    {[lp110of200,lp110of020]}, ... %[output:16cc5ecb]
    lp110of200,[0,0.005,0.5],othrEi400cut110{:},'-combine'); %[output:group:80995a45] %[output:16cc5ecb]
plot(w2ei400NGoff200maxFF);liny; lz 0 1;keep_figure; %[output:8d28864d]


%%

NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ... %[output:group:4144f2fd] %[output:38027712]
    'Ei400_off200NGmaxFF',cut(w2ei400NGoff200maxFF,[0,0.005,0.5],[10,2,250])); %[output:group:4144f2fd] %[output:38027712]

save(masks_file,'cuts2fit400NG','-v7.3');
%%
lpM110of200 = line_proj([-1,1,0],[1,1,0],'offset',[2,2,0]);
w2_400NGoff220minFF = cut(src400sym,lpM110of200,[0,0.02,3],othrEi400cut110{1:2},[0,2,320], ...
    SymopReflection('normvec',[-1,1,0],'offset',[2,2,0]));
plot(w2_400NGoff220minFF);lz 0 0.1; keep_figure %[output:825aace9]
%%
bg1D = cut(w2_400NGoff220minFF,[1,5,2],[]);
plot(bg1D);logy;keep_figure; ly 0.005 1; %[output:7fe5d936]
%%
q0=0.77 %[control:slider:60a6]{"position":[4,8]} %[output:56553217]

%q0=-0.475
w1ei400dE = cut(w2_400NGoff220minFF,[q0-0.025,q0+0.025],[]);
plot(w1ei400dE);liny; ly 0 0.1 %[output:938e07fd]
%%
w2_400NGoff220minFFr = cut(w2_400NGoff220minFF,[0,0.01,1],[10,2,295]);
NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei400_off220NGminFF',w2_400NGoff220minFFr);
w2_400NGoff220minFFrs = smooth(w2_400NGoff220minFFr) %[output:36a5b983]
plot(w2_400NGoff220minFFrs);liny;lz 0 0.1; keep_figure %[output:7d2a84c7]


